using namespace std;

int main() {

	int N;
	cin>>N;

	string S;
	cin>>S;

	bool f1 = false;
	for(int i=0;i<N;i++){
		if(S[i]=='o')f1 = true;
	}

	bool f2 = true;
	for(int i=0;i<N;i++){
		if(S[i]=='x')f2 = false;
	}

	if(f1&&f2)cout<<"Yes"<<endl;
	else cout<<"No"<<endl;

	return 0;
}
